INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p389994-mkt398', 'stk-jotun', 'MKT 398', 'info', '{"desc": "http://img23.imageshack.us/img23/2664/coopl.jpg\n\nJotun is looking for Co-op Trainees in the following Majors:\n\n**\\(1\\) Industrial engineer in Yanbu.****\\(1\\) Chemical engineer in Jeddah or Yanbu.****\\(1\\) Mechanical engineer in Yanbu.****\\(1\\) Accountant in Jeddah.****\\(1\\) HR position in Jeddah \\(Industrial Engineer, Marketing or Management\\).** We offer:\n\n- A professional working environment that focuses on continuous improvement and innovation.\n\n- An international corporate culture founded on our four values; Loyalty, Care, Respect and Boldness.\n\n- Contract for each student with a monthly salary of SR 3000 (Basic Salary: 2400, Housing Allowance: 500 and Transportation Allowance: 100).\n\n- Prepared Co-op plan for each position.\n\n- Working hours 7:30 AM to 5:00 PM from Saturday to Wednesday.\n\n- Trainees will perform On-Job projects during the Co-op Period.\n\n- One week vacation will be given during the Co-op\n\nIn addition, competent trainees will have an opportunity to Join our family after graduation.\n\nC.V.s will be received & Exams will be held during the Career Day Event on 12-16 April.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/co-op-opportunities-in-jotun/72286/1", "user": "JOTUN", "ts": 1239280300000, "tid": 72286, "pn": 1}}', 1239280300000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1511463-mkt398', 'stk-rami_ali_ce_1990', 'MKT 398', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\n1- يتوفر فرصة تدريب تعاوني بمسمى | Marketing Intern\n\nالمؤهلات العلمية : تخصص ادارة او تسويق( Management or Marketing)\n\nالمهارات الشخصية : شخص منظم جدا وتماما، مهارات تواصل\n\nمعلومات : اذا اثبت الشخص نفسه سيكون هناك فرصة لعقد يتجدد بشكل سنوي\n\nالمكان : الشرقية او الرياض\n\nالجنس | ذكر او انثى\n\n2- فرصة وظيفة بمسمى | Marketing Coordinator\n\nالمؤهلات العلمية : تخصص ادارة او تسويق( Management or Marketing) يفضل حديث تخرج\n\nالمهارات الشخصية : شخص منظم جدا وتماما، مهارات تواصل\n\nمعلومات : دوام مريح مافي تدقيق عالحضور والانصراف\n\nالمكان : الشرقية او الرياض\n\nالجنس | ذكر او انثى\n\nالرجاء التواصل عالخاص لاي استفسار او ارسال السيرة الذاتية على ali.r.g.mohammed@gmail.com\n\nودمتم بود يا شباب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/181661/1", "user": "Rami_Ali_CE_1990", "ts": 1561284451000, "tid": 181661, "pn": 1}}', 1561284451000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p367566-mkt398', 'stk-chemical-983', 'MKT 398', 'info', '{"desc": "و عليكم السلام و رحمة الله و بركاته\n\nأخي الكريم…أبو ناصر الراجح\n\nالفرق بين الهندسة الكيميائية Applied و Science في المستقبل الوظيفي ليس مهما جدا في التوظيف , فليس من الضروري تطبيق التدريب التعاوني في شركة ما يعني التوظف فيها , هناك الكثير ممن تدربوا في شركات و لم يعملوا بها بعد التخرج , فالشركات الكبرى مثل ارامكو و سابك تركيزهم في التدريب على طلابهم الذين لهم الأولوية و الشركات المتوسطة - غالبا المساهمة - تقدم التدريب و لا تعد بعده بالتوظيف بعد التخرج و الشركات الصغيرة توفر التدريب فقط من باب التسويق و لا مانع من قبول خريج البترول الذي يعتبر مكسبا لها - خصوصا مع رواتبهم المتدنية و ضعف نسبة السعودة , فتكون ضربت عصفورين بحجر مهندس جيد براتب قليل و رفع السعودة امام مكتب العمل.\n\nو لكن الفرق اعتبره جوهري بين القسمين من الناحية الأكاديمية و المستقبل المهني …\n\nمن الناحية الأكاديمية… خرّيج العلوم الهندسية , مهيأ لإكمال دراساته العليا في التخصص . و تدريبه الصيفي الذي هو عبارة عن نجاح و رسوب فقط , يتيح له ان يستفيد اكثر - رغم قصر الفترة نسبيا - لأنه لا يعاني من الضغط النفسي الناتج من الساعات الأكاديمية و لا يربط تحسين معدله بالتسع ساعات , كما يعاني خريج الهندسة التطبيقية , ونظرة الشركات لدرجة هذه التسع ساعات غالبا تملؤها الريبة ( غالبا تكون A أو B ) و يعتقدون بأن الطالب تم منحه هذه الدرجات ليس بناء على جودة العمل بل كمّيته ( و هذا يحتاج موضوع منفصل) , عوضا عن ان خرّيج التطبيقية لا يسمح له بإكمال الدراسات العليا في التخصص ( و هذا ما قاله لنا الدكاتره حينها - و لا اعلم الآن عن الوضع )…\n\nو من ناحية المستقبل الوظيفي, خرّيج الساينس يتفوق من ناحية المعرفة المتقدمة بالتخصص ( 9 ساعات = 3 مواد اختياريه متقدمة تعتبر مثل المدخل للماجستير ) و هذا افضل للشركات من التدريب الذي لا يخدمها غالبا ( إلا إذا كان لديها - و كنت قد ذكرت ان ليس كل متدرب = موظف) و الإلمام ببيئة العمل بشكل عام تكفيه شهور قلائل و هو المتوافر لطالب الساينس , خصوصا انه يكون في بيئة مثالية للملاحظه و التلقّي Observation environment و يستفيد اكثر في هذا الجانب و لا يتم استغلاله من قِبَل الشركات لأنه ليس لديه نقطة ضعف يضغطون عليه عن طريقها ( التسع ساعات) , بخلاف طالب الأبلايد الذي يذهب وقته في مهام للشركة التي تنظر له كعمالة رخيصه و ذكيه في آن ( و آسف على التعبير لكنه ناتج عن خبره) و لا يتفرغ للريبورت إلا في آخر شهرين او ثلاثة اشهر و ايضا بشكل جزئي , و هو يخشى إن لم يرضي الشركة فستتم معاقبته في التقييم و يتحصّل على درجه اقل مما كان يأمل و بنى عليه لتحسين المعدل …\n\nطالب الساينس, يستفيد من المواد الإختيارية - و هذا يعتمد على المواد نفسها و طبيعه نشاط الشركة التي يعمل بها - و هذه الفائدة حاصله إن شاء الله لو قارنت بين مبدأ المعرفة المتخصصة ام العمل ؟ ( ولا ننسى ان طالب السينس يعمل ايضا !) و ايهما يكسب في نهاية المطاف ؟ و هذا يجعل له التفوق العلمي على طالب التطبيق , في آخر المطاف …\n\nالأبلايد كفكره بدأت مثاليه و لكن تمت اساءة استغلالها من الطالب الذي يبحث عن الدرجة و الشركة التي تبحث عن عمالة رخيصه بعقلية مهندس ( و اعتذر مرة اخرى)…\n\nلهذا انا مع الساينس - في تخصصي فأنا لا افتي في تخصصات غيري - , حتى ينصلح الهرم المقلوب و تطبق الفكرة روحا و نصّا ! , وهذا يحتاج لضغط من الجامعة و ترك المجاملات جانبا , فما تقدمه الشركات من دعم للتدريب التعاوني هو في صالحها في النهاية ( فهي التي تستقبل مخرجات الجامعة بعد التخرج) و ليس منّة منها على الجامعة و طلّابها…\n\nو للمعلومية أنا ساينس و لست متحيزا ( لأني نسيت الفرق بعد التعيين مباشرة و احسست بعد بضعة سنوات بالمقارنة مع اقراني و مع الخبره في الإشراف على النوعين اثناء تدريبهم في شركتي السابقة) ولا اعتبر مهندسا كيميائيا الآن سوى بالخلفية الهندسية فقط , ولا اعمم بكلامي و لكن - كالعاده - الفكره غير التطبيق , و أنا اتكلم عن واقع مشاهد و محسوس من خبرة شخصية تقارب 10 سنوات …\n\nاتمنى لك التوفيق و السداد … و لا تتردد في الإستفسار عن ما لم استطع ايصاله بوضوح في هذه العجالة لأني كتبت الرد بسرعه … و سامحونا على القصور\n\nأخوك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/applaied-vs-science/70487/7", "user": "Chemical-983", "ts": 1234677392000, "tid": 70487, "pn": 7}}', 1234677392000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1520417-mkt398', 'stk-ahmad.ah', 'MKT 398', 'info', '{"desc": "فرص تدريب لدى Unilever\n\nUnilever Internship Program - Customer Development\n\nUnilever Internship Program - Marketing\n\nUnilever Internship Program - Human Resources\n\nUnilever Internship Program - Finance\n\nUnilever Internship Program - Supply Chain", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/182745/9", "user": "Ahmad.AH", "ts": 1583081148000, "tid": 182745, "pn": 9}}', 1583081148000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p60564-mkt398', 'stk-redeemer', 'MKT 398', 'info', '{"desc": "السلام عليكم أخواني\n\nكيف حالكم عساكم بخير عسى مابوه خبيث<<<---أقول إخلص 😠\n\nمالكم بالطويلة,إحم\n\nحالياً أطبق بالرياض من الصيف اللي طاف في (يحتفظ العضو باسم المنشأة:D )\nطبعاً مابي أقول لكم كيف إتنكبت فيهم شر نكبة وكلامهم عند المقابلة غير والواقع غير,ومن الأول كيف عارضين عند الجامعة راتب 4000 ريال ولمن جيت قالوا لي لك 2500 ريال وقالوا لواحد ميكانيكل لك 2000 ريال بس.\n\nالشغل هنا ميييح ماكو شغل بالمرة لمجال تخصصي التسويق MKT .\nكلمت الأدفايزر قالي حاول ترص ع المسؤول لازم يشوف لك شغلة ولا كان ماطلبوا من الأساس يبون طالب تسويق.\n\nالقهر الكوأب بيخلص ولحد الحين أعصر مخي أبي أشوف حاجة أكتب فيها البلية الريبورت مافيه 😦\n\nعلشان يشغلني المسؤول هنا قام يعطيني شغلات مال أمها داعي بالتخصص وحاجات تافهة,من ضمنها يبيني أعمل خطوات إعداد ورشة عمل متكاملة.\n\nياهوو يابو الشباب وشو أسوي لك ورشة عمل خطواتها وأنا ماعمري طبيت في هالمجال وأصلاً مادرسناها ولا لي شغل فيه…القهر قالها لي إنهم بيتعاونوا مع شركة متخصصة في إدارة ورش العمل,يعني تزحمني ليش طيب,\n\nكتبت وسويت اللي أقدر عليه ورسلته له بالإيميل,المدير والمسؤول مسافرين بالخارج لغرض الشغل إسبوع وراجعين,اليوم الأحد تجيني رسالة من عند المسؤول وهو بالخارج أنقلها لكم:\n\nالاستاذ *******\nتحية طيبة\nوصلتني عناصر ورشة العمل ولايزال الشغل غير كامل وغير مرتب ولم يضع في جهد كبير ارجو العمل الجاد على التفصيل بعناصر الورشة وعمل تفصيل لكل خطوه بالاضافه الى التفكير العميق بخطوات عمل الورشة ومن ثم وضعها على جدول زمني على المايكورسوفت بروجكت\nعلماً بانني ويوسفنى ان اقول هذا الشي ولكن عدم جديتك بالعمل اجبرت ادارة المشروع على التعامل بهذه الطريقه لذلك اذا لم يتم انجاز العمل بالجوده المطلوبة والوقت المطلوب وهو يوم السبت القادم10/10 سوف يتم خصم خمس ايام من مكافئتك وخمس درجات من مجموعك بالتقييم\n\nهذا واتمنى العمل الجاد\nوتقبل التحية\n\nوربي أنواع ألوان الطيف كلها جتني من قريت الرسالة,شيبو ذولا الشغلة إذلال يعني ولا كيف؟؟؟…جاني تفكير أخرب أم الدنيا وإحتمال أدخل قضية إعتداء بالضرب عليه ,خلاص قفلت عندي,يعني شقول لكم,اللي معي من البترول ميكانيكل كمان,وربي يخلوه يسوي كروكي من المطار لمحل الشغل إذا بيجيهم ضيف من الشرقية أو من حيالله محل,يسوي تصحيح إملائي لشغلات,تصميم كروت ,بزنز كارد,وماخفي كان أعظم…\n\nشغلة ورشة العمل اللي سويته زي ماطلبه بشكل عام يعني لسه ماتحدد أي شي وسويته له بالماكيروسوفت بروجيكت ويرجع يطلبه ثانية:\n\n1) تحديد عنوان وموضوع ورشة العمل.\n2) إعداد أجندة الورشة.\n3) إعداد قائمة بالجهات و باسماء الأعضاء وتحديد نوعية مشاركتهم كحضور أو كمتحدثين.\n4) تنسيق كل مشاركة لكل متحدث من حيث التنظيم والوقت.\n5) إعداد بروشورات للحضور.\n6) توزيع إستمارات للإستبيان لجميع المشاركين والحضور.\n7) Key Person - تحديد الشخص المسؤول عن إدارة الورشة.\n8) إيجاد مكان مناسب لإنعقاد ورشة العمل بأخذ إعتبار الموقع الجغرافي وملائمته لإستيعاب الحضور وعددهم وأهميتهم.\n9) حجز المكان وتهيئته.\n10) تحديد رسوم مالية للإشتراك إن أمكن.\n11) إيجاد الطريقة الأنسب للإعلان بإختيار الوسيلة المناسبة.\n12) إنعقاد الورشة.\n13) جمع وتحليل إستمارات الإستبيان من الحضور.\n14) إستخلاص نتائج الإستبيان ومدى ملائمتها لأهداف إنعقاد الورشة المرجوة.\n15) النتائج والتوصيات.\n\n=-=-=\n\nمثل ماتلاحظوا يبغى شي عام بدون تحديد لا اسم ولا مواضيع ولا أي حاجة يعني كذه خطوات إنعقاد ورشة عمل,طيب أنا اللي طلع مني هذا وش أقدر أسوي بالله عليك بشي أنا ماجيت أطبق عندك علشانه,وشوفوا كيف بالرسالة شيقول فوق.\n\n=-=-=\n\nشباب وش نصيحتكم لي الله يرضى عليكم,منتظر مساعدة للي يعرف بورش العمل وهم مساعدة وش أسوي مع هالمخلوق لأني وربي ناوي شر بس مركد حالي قلت أستشير أخواني بالأول هنا ,لأني بالنهاية لو قومتها خناقة هو مو خسران حاجة.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/co-op/40721/1", "user": "RedeemeR", "ts": 1096808551000, "tid": 40721, "pn": 1}}', 1096808551000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p33274-mkt398', 'stk-mkt_99', 'MKT 398', 'info', '{"desc": "اهلين حبيب قلبي\n\nبالنسبه للكووب تقدر تطلع حتى لو ماتخلص كم مادة تخصص\nانا جيت للشيرمن وقال تطلع كووب اذا خلصت الMKT 345 ويكون معها كم مادة بدون تحديد واذا بقى اربع مواد واقل يتغاضون عنهابس اهم شي تخلص 345\n\nوبالنسبه للمادة اللي تنزل في السمستر الثاني فيمكن ينزلوها كل سمستر في حاله وجود مدرسين كفايه مثلا هذا السمستر جاء دكتور جديد اسمه طاهر ونزلوا مادتين اللي هي 330 و 340 وهي ماتنزل الا في السمستر الثاني\n\nمايبقى الا نقول عساها تلقح وينزلون مادتك في السمستر الاول وحاول تشوف زملاء لك ماخلصوها وتقدمون خطاب للشيرمن عساه يساعدكم\n\nوسلامتكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop-mkt-400/26683/2", "user": "MKT_99", "ts": 1063801383000, "tid": 26683, "pn": 2}}', 1063801383000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1441794-mkt398', 'stk-user8581', 'MKT 398', 'info', '{"desc": "شفت فيه تقديم لفرصتين كواب في سابك لكن ما ادري اذا هو مفتوح للطلاب السعودين او لا فياليت الي عنده فكرة عن الموضوع او تواصل معهم يفيدنا ويصحح لي لو كنت غلطان\n\nعلى العموم الفرصتين المتاحتين هم في امريكا\nاول شي ادخل على هذا الرابط وسو حساب\nCurrent Vacancies | ظˆط¸ط§ط¦ظپ ط´ط§ط؛ط±ط© | ط§ظ„ط£ظ…ط±ظٹظƒطھظٹظ† | ط§ظ„ظˆط¸ط§ط¦ظپ | ط³ط§ط¨ظƒ\n\nتالي Search openings\nوابحث عن Co-op وراح تظهر لك فرصتين وراح يكون التدريب في امريكا …الفرصة الأولى في Indiana والثانية في Alabama\n\nوهذي المتطلبات في الفرصة الأولى\n\n[table=“width: 92%, align: center”]\n\n[td=“colspan: 2”]https://sjobs.brassring.com/TGWebHost/images/pixel.gif\n\nPosition Title\n[td=“class: tgalignleft, width: 80%”]Early Identification Program (EID/Co-op)\n\nAuto Req ID\n[td=“class: tgalignleft, width: 80%”]6757BR\n\nRe******** Assistance\n[td=“class: tgalignleft, width: 80%”]Yes\n\nRegion/Pole\n[td=“class: tgalignleft, width: 80%”]Americas\n\nFunctional Work Area\n[td=“class: tgalignleft, width: 80%”]Engineering\nManufacturing\n\nJob Purpose & Responsibilities\n[td=“class: tgalignleft, width: 80%”]At SABIC, we provide exceptional opportunities for engineering students to spend a semester doing real engineering work. Whether it’s in Operations, EHS&S, or Reliability, SABIC offers an array of different opportunities to help students develop the skills needed for a career after graduation.\n\nSABIC EIDs will work on meaningful projects that have real impact for the business under the guidance of some of our best engineers. They will receive on the job training, exposure to different parts of the business and mentoring from members of our leadership teams. In addition, they will build support networks with other EIDs and have the opportunity to be part of a pipeline into the SABIC Engineering Early Development Program (SEED) – a two year rotational program consisting of four, 6 month roles and two geographical ********s.\n\nDuring the program, EIDs will be assigned to experience the following types of assignments:\n\nChemical Operations;\n\nCompounding;\nReliability;\nEnvironmental, Health, and Safety.\nProgram placements will be based on technical development needs, availability of assignments and personal preference. Pay is competitive and re******** is available for those qualify.\n\nRequirements\n[td=“class: tgalignleft, width: 80%”]Requirements:\n\nPursuing a Chemical or Mechanical Engineering Degree with a 3.0/4.0 GPA\n\nEligibility Requirements:\n• You must submit your application for employment online to be considered. Please submit your resume using the apply online option on this page.\n• You must be 18 years or older\n• You must be willing to take a drug test as part of the selection process\n• You must be willing to submit to a background investigation as part of the selection process\n• You must have unrestricted authorization to work in the United States\n\nFor U.S. employment opportunities, SABIC Innovative Plastics hires U.S. citizens, permanent residents, asylees, refugees, and temporary residents. Temporary residence does not include those with non-immigrant work authorization (F, J, H or L visas), such as students in practical training status. Exceptions to these requirements will be determined based on shortage of qualified candidates with a particular skill. SABIC Innovative Plastics will require proof of work authorization prior to employment.\n\nCountry\n[td=“class: tgalignleft, width: 80%”]United States of America\n\nCity\n[td=“class: tgalignleft, width: 80%”]Evansville\n\nState/Province\n[td=“class: tgalignleft, width: 80%”]Indiana (IN)\n\nGeneral\n[td=“class: tgalignleft, width: 80%”]People Who Can\n\nWe’ve always believed that it takes special people to make a difference. They need ingenuity, brilliance and the freedom to turn their ideas into reality. At SABIC, this is our culture. We find open-minded, gifted and questioning people. Then we create the conditions for their talent to flourish: fulfilling work environments, state-of-the-art technology and the empowerment they need. So when you work for SABIC, you’re the person who can find new solutions and possibilities that change the world for the better.\n\nSABIC, headquartered in Riyadh (Saudi Arabia), is one of the world’s leading manufacturers of chemicals, fertilizers, plastics and ****ls. We supply these materials to other companies, who use them to make products on which the world has come to depend. At SABIC, we believe in using chemistry to power the ambitions of our customers, business partners, employees and societies we live in. We call this “CHEMISTRY THAT MATTERS™”.\n\nIn the Americas, SABIC employs over 5,000 people and is running 17 manufacturing sites, 5 technology and innovation centers. We are present in 7 countries with 17 offices. Major ********s within our broad network of innovation, production and marketing are: Evansville (IN, USA), Houston (TX, USA), Pittsfield (MA, USA) and Selkirk (NY, USA). With the acquisition of GE Plastics in 2007 we are a key producer of engineering thermoplastic resins, films and sheets. Discover more at sabic.com/careers\n\nAs an Equal Opportunity Employer, SABIC will not discriminate in its employment practices, including recruiting and hiring practices, based on an applicant’s race, color, religion, national origin, sex, sexual orientation, age, disability, veteran status, marital status, genetic information or other category protected by law.\n\nDisclaimers (USA):\n\nSABIC is not accepting unsolicited assistance from search firms/employment agencies for this employment opportunity. Please, no phone calls or emails to any employee of SABIC about this opening. All resumes submitted by search firms/employment agencies to any employee at SABIC via-email, the Internet or in any form and/or method without a valid written search firm agreement in place for this position will be deemed the sole property of SABIC; no fee will be paid in the event a candidate is hired by SABIC as a result of the unsolicited referral or through other means.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/161-152-153/170272/53", "user": "user8581", "ts": 1455145184000, "tid": 170272, "pn": 53}}', 1455145184000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p172520-mkt398', 'stk-user3', 'MKT 398', 'info', '{"desc": "ذهبت مُسرعاً لكي ألتقي به, فوجدته ينتظرني بكل تواضع و هدوء. لقد توقعت أن رجلاً في منصبه سيسألني عن طريقة لباسي او لماذا لم أحلق ذقني… او شيء من هذا القبيل… لكن شيئاً من هذا لم يحدث, فلقد استقبلني و أجلسني بجانبه و كأنني أعرفه منذ مدة ليست بالقصيرة… كنت أتتوقع أن أجواء من السكون و السكوت ستخيّم علينا, إلا أنه بادرني بأمطار من الأسئلة عن المنتدى و عن نشأته… أخذ يسألني عن كل صغيرة و كبيرة مما أثار حماسي المُطلق. أخذت أسرد له قصة هذه السفينة, و لقد تعجبتُ حينما أخبرني بأنه قد زار المنتدى في السابق (منذ سنتين تقريباً) بهدف التعاون مع المنتدى لحجز (بانر) دعائي للشركة التي كان يعمل فيها وقتئذٍ …Unilever.\n\nثم بادرني بالأسئلة الشخصية… و مع تبادلنا لبعض المعلومات إكتشفتُ أن هذا الرجل حريص على التوظيف و محاربة البطالة… فتجده يتنقل من منتدى لآخر يعرض فيه وظائف في الجهة التي يعمل بها, وهذا على حد علمي, عملٌ لا يقوم به إلا رئيس متواضع للناس ولا يتغير بتغيّر منصبه…\n\nhttp://j.loading.googlepages.com/KFUPMcareerday.JPG\n\nنرحب جميعاً بالأستاذ /طارق الكاهلي - رئيس قسم التوظيف في بنك ساب. و يطيب لنا أن نعرض لكم الأسئلة التي عُرضت عليه و تفضّل بإجابتها…\n\n1) عرفنا بنفسك… إسمك… سنة التحاقك بالجامعة… التخصص… سنة التخرج…الخبرة الوظيفية\n\nطارق حسين الكاهلي، دفعة 97. تخرجت من الجامعة في عام 2002 من قسم هندسة نظم. عملت في الوظائف التالية:\n\n2001 تدريب تعاوني - شركة يونيليفر\n2002 مدير تحت التدريب – يونيليفر\n2004 مدير التوظيف – يونيليفر\n2005 مدير توظيف الخريجين - الشرق الأوسط - يونيليفر\n2006 و حتى تاريخه، رئيس إدارة التوظيف – بنك ســـاب\n\n2) نبذة عن موقعك الوظيفي في البنك, و عن الأعمال التي تقوم بها في هذا القسم؟\n\nأقوم بقيادة فريق عمل يعنى بالآتي:\n\n- تسويق البنك عبر مختلف الجامعات و المعاهد و القنوات المناسبة لإستقطاب الكفاءات الشابة للبنك\n- إدارة مركز قياس و تقويم لتقييم قدرات المتقدمين و أيضا لتقييم موظفي البنك لأسباب تطويرية\n- استقطاب متقدمين ذوو خبرات\n- استكمال الإجراءات الإدارية للمنضمين الجدد للبنك لجعل انضمامهم للبنك يتم بكل يسر و سهولة\n- تطوير قدرات البنك في التوظيف من حيث تطوير الكفاءات الشابة في الإدارة، وتطوير الإجراءات و أنظمة المعلومات التي تساند الفريق في أداء عمله.\n\nhttp://j.loading.googlepages.com/1-t.JPG\n\n3) حدثنا عن مرحلتك التعليمية من الابتدائية و حتى المرحلة الثانوية؟\n\nابتسمت عند هذا السؤال… الحقيقة رحلة الدراسة كانت غريبة نوع ما. فقد درست أغلب الإبتدائية في مدارس الأندلس لكن انقطعت لسنة و نصف لمرافقة والدتي {أطال الله في عمرها} في بريطانيا حيث كانت تدرس. ثم عدت للمملكة و أكملت دراستي حتى الأول ثانوي، عندها درست منهج الثانوية البريطانية في نفس عام الأول ثانوي. و كنت أدرس بالنهار في مدارس الثغر و بالليل أدرس منهج الثانوية البريطانية، والتي أهلتني لدخول الجامعه فور انتهائي من تلك السنة.\n\n4) لماذا إخترت جامعة الملك فهد؟ و هل لالتحاقك بالجامعة قصة؟\n\nأخي كان التحق بها قبلي و كان يشيد بالجامعه كثيرا. لم يكن هناك قصة أذكرها، لكني لا أنسى من ذلك دموع والدي عندما اتصلت الجامعة لإخباري بالقبول.\n\n5) السنة التحضيرية “الأوريا” لها ذكرياتها في ذهن كل طالب جامعي… فما هي ذكريات الأستاذ طارق الكاهلي مع عالم الأوريا (بقليل من التفاصيل)؟\n\nأخبروني أن علي ان أراجع مبنى 17 لأخذ البطاقة و انهاء بعض الإجراءات. كانت نقطة الإنطلاق لاين 647 حيث سكنت في أول اسبوع مع أخي. بالطبع دخلت أول مبنى صادفني، باحثا عن رقم المبنى من الداخل حيث لم أجد أرقام على واجهة المبنى، هذا كان في سبيل أن أستدل من رقم المبنى على مبنى 17. بعد ان دخلت المبنى وجدته مظلما من الداخل و به سراديب مظلمة و خرج لي شخص بسروال سنة من غرفته ليخبرني بمتعة، انني كنت في العماير البنية و ليس الجبل.\n\nhttp://j.loading.googlepages.com/2-t.JPG\n\n6) موقف لازلت تذكره في السنة التحضيرية؟\n\nأخبرني في أول أسبوع لي بالجامعة، عميد الأوريا آنذاك د.فهد السعيـد، انني سأفصل من الجامعة إن رسبت في الـ Math لأنها كانت مع الرياضة و الـ shop المواد الوحيدة في جدولي. اجتهدت خوفا من الفصل و حصلت على مرتبة شرف أولى.\n\n7) ما سبب إختيارك لتخصصك؟ و هل كنت تواجه صعوبات في إتخاذ القرار؟\n\nأعجبني قدرة مهندسي النظم في زيادة الإنتاجية عن طريق حسابات هندسية وإدارية و هذا الذي جذبني.لم تكن كل القرارات سهلة طبعا، هناك قرارات صعبة اتخذتها.\n\n8)هل لك تجارب في عالم النشاط الطلابي؟ و ما مدى تأثيرها الإيجابي عليك كطالب في الجامعة؟\n\nنعم كنت عضو في نادي العلاقات العامة. كان لها فضل كبير بعد الله في تطوير قدراتي الشخصية، بالإضافة لتكوين مجموعة متميزة من الأصدقاء، أعتز بهم إلى هذا اليوم.\n\n9) أسماء دكاترة و أساتذة تدين لهم الكثير, لا زالت عالقة في ذهنك؟\n\nد. فؤاد السني، د.عبدالباسط أنديجاني، و د.عمر التركي. كما أدين كثيرا لأساتذتي في الحياة الذان علماني خير دروس ما زالت ترشدني إلى اليوم، والدي حسين الكاهلي ووالدتي د. أسماء باهرمز، أسأل الله أن يحفظهما و يطيل في أعمارهم.\n\n10) ما هي أبرز هوايات طارق الكاهلي؟\n\nالسفر، القراءة، العلاقات الإجتماعية و ركوب الخيل متى ما أمكن.\n\n11) هل تفكر في إكمال دراستك العليا قريباً؟\n\nلا.\n\n12) هل تنصح الخريج أن يتوظف أولاً… أم يكمل برنامج الماجستير؟\n\nالجامعات المرموقة التي تقدم برامج MBA أغلبها تطلب خبرة سابقة قبل الإلتحاق ببرنامج ماجستير، وأنا أتفق معها في الرأي.\n\n13) لماذا يركز القطاع البنكي في توظيف الخريجين تحت برنامج (Corporate Finance), مالمميز في هذا المجال الذي يجعل أغلب البنوك توظف فيه؟\n\nيكون لدى خريجين ال Finance خلفية جيدة في عمليات البنك المختلفة والأسس التي تعمل بها. لكن يجب التنويه أن الإدارة البنكية ليست علم نووي و يمكن لخريج أي تخصص أن يتقنه.\n\n14) ما هو موقفكم من سياسة “الحشو التوظيفي”… مثلاً أن يأتي خريج في الهندسة الصناعية و يتم توظيفه في قسم الإدارة المالية؟\n\nالرئيس التنفيذي لأحد البنوك العالمية في المملكة خريج كلية جوية، وهناك أمثلة كثيرة. كما قلت سابقا، ليس هناك علم نووي في الموضوع، و من لديه رغبة في مجال، سيتعلمه.\n\nhttp://j.loading.googlepages.com/3-t.JPG\n\n15) يقال أن الخريج حينما يختار إكمال دراسته العليا, فإنه يواجه صعوبة في الحصول على وظيفة نظراً لانعدام الخبرة التي تتطلبها الجهات التوظيفية… هل هذه المقولة صحيحة؟ و ماهي الطريقة السليمة للتوفيق بين إكمال الدراسة و الحصول على وظيفة؟\n\nللعمر دور، حيث أن الخريج يسهل عليه الإلتحاق بوظائف كثيرة عندما يكون في حدود ال25 عاما فأقل، أما بعد ذلك، فيجب أن يكون لديه خبرة تشفع له، إذا ما أراد الحصول على وظيفة مرموقة. الإنطلاق في الدراسات العليا يجب ان يكون مدروسا ومخططا، ويؤسفني بعض الأمثلة من الشباب الذين –يمطون- في دراساتهم العليا فيأخذ double major ثم ماجستير أو ربما اثنين. كثيرا يكون هذا في سبيل البقاء في الخارج أطول فترة ممكنه، ثم يستيقظون في عمر ال 26 إلى 30 و هم لا يملكون أي خبرة و يبحثون عن فرص.\n\n16) بحكم خبرتك في مجال التوظيف, ما الذي يميز خريج جامعة البترول في نظرك عن أقرانه من خريجي الجامعات الأخرى؟\n\nشهادتي في خريجي جامعة البترول مجروحة، و لكني أظن انه لو لم تكن هناك جامعه أخرى في المملكة غيرها لكفت.\n\n17) ما هي النقاط التي تتمنى لو كانت موجودة بقوة و بكثافة في خريج جامعة البترول, او بمعنى آخر… تتمنى أن تتوفر في خريج البترول؟\n\nربما ينقص الجامعة ما يسمى بـ diversity و هو التنوع الثقافي من حيث جنسيات الطلاب. فلو كان موجودا لطور في الطلاب مهارات التعامل مع الثقافات الأخرى و هذا مطلوب في العالم اليوم و يمكن الحصول عليه عن طريق العمل مع أجانب في شركات معينة.\n\n18) لقد عملت في شركة كبرى قبل التحاقك بـ ساب. أنا أجزم بأنك صادفت مجموعة ليست قليلة في كلا الجهتين, من خريجي الجامعة… هل نستطيع أن نقول بأن خريجي جامعة البترول هم العامل البشري المؤثر و الأساسي في كلا القطاعين؟\n\nنعم، لهم نصيب الأسد من الوظائف القيادية.\n\n19) أين ترى نفسك كخريج من جامعة الفهد, بعد عشرة سنوات؟\n\nأن أكون قادرا على خدمة الجامعه بشكل خاص، وخدمة المجتمع بشكل عام و ذلك حسب اختصاصي عن طريق المساهمة في تطوير أبناء المملكة مما يكون له مردود إيجابي على الإقتصاد، فشبابنا هم النفط الذي لا ينضب بإذن الله.\n\n20) ماذا تنصح إخوانك الطلاب و المقبلين على التخرج قريباً؟\n\nالطريق شيق و ممتع أمامكم، و هناك الكثير مما يمكن أن تضيفوه حيث أنكم النخبه و الجميع ينتظر منكم الكثير أيضا، فالهمة الهمة.\n\n21) هل صحيح أن المعدل هو المقياس الحقيقي للتوظيف بشكل عام؟\n\nلا\n\n22) قمتَ بإلقاء محاضرات تعريفية أكثر من مرة في قاعات الجامعة, مالإنطباع الذي ترسخ لديك من طلاب الجامعة مقارنة بالوقت الذي كنت فيه طالباً مثلهم؟\n\nلا أتذكر جيدا لأنني في وقت دراستي لم أكن أقيم الآخرين. لكنني أفرح كثيرا عندما أقابل نخبة من الطلاب أرى فيهم عوامل النجاح و أنا متأكد أنهم سيكونون في مواقع مرموقة بإذن الله بعد عدد من السنين.\n\n23) ما فائدة اللقاءات مع الطلاب في نظرك؟ و مالنتيجة المرجوة من طرفكم كإدارة توظيف؟\n\nالتسويق لإسم البنك و من ثم اختيارها الطلاب للتوظيف عند تخرجهم.\n\n24) ما هو رأيك في منتدى طلاب جامعة الملك فهد للبترول و المعادن sKFUPM ؟\n\nمنتدى رائع و أتوقع للموقع مستقبل باهر، بالذات إذا تم تفعيله مع الأندية الطلابية و نادي الخريجيين. إلى الآن لا نملك وسيلة فعالة للتواصل بين الخريجين و قد يكون مثل هذا المنتدى وسيلة فعالة.\n\n25) يتميز منتدانا بمتابعة حثيثة من قبل مسؤلي الجامعة و على رأسهم معالي الدكتور خالد السلطان… هل سبق و فكرتم في التواصل مع خريجي الجامعة عن طريق المنتدى؟\n\nنعم لدينا خطط لهذا و لكن لا أستطيع الإفصاح عنها الآن.\n\n26) رسالة تود أن يقرأها أعضاء منتدى sKFUPM ؟\n\nأتمنى أن يكون هذا اللقاء ذو فائدة و أتمنى أن يثمر المنتدى في الحفاظ على التواصل بين أبناء الجامعة خلال دراستهم و بعد تخرجهم.\n\nhttp://j.loading.googlepages.com/4-t.JPG\n\nشكراً جزيلاً للأستاذ طارق الكاهلي على وقته الثمين, وعلى تجاوبه مع المنتدى… وإلى أن نلتقي معكم في لقاء آخر مع شخصية قيادية أخرى تخرجت من هذه الجامعة, لكم مني أجمل و أزكى تحية 🙂\n\nابو سمر … sKFUPM … الرياض\n\n@46@", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/56618/1", "user": "user3", "ts": 1180638342000, "tid": 56618, "pn": 1}}', 1180638342000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1150610-mkt398', 'stk-user198', 'MKT 398', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته…\n\nيبدو أن الموضوع متأخر جدا ولكن أحببت الاعلان عنه وهو: يوجد شاغر واحد للتدريب التعاوني لطلاب التسويق في شركة متخصصة بتقنية المعلومات بالرياض…\n\nالرجاء التواصل معي علخاص… بأسرع وقت ممكن (قبل الأربعاء 2 يناير 2013م) (ستعطى الأولوية لمن تقدم أولا وانطبقت عليه الشروط)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/137176/1", "user": "user198", "ts": 1356857839000, "tid": 137176, "pn": 1}}', 1356857839000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1216314-mkt398', 'stk-user2528', 'MKT 398', 'info', '{"desc": "We are looking for a talented CS/SWE/MKT to join our team in the COOP/Summer prgrammes in Khober. A highly skilled team with flat hierarchies, a creative environment and a lot of fun makes. If you love your major and passionate about it send us your CV & your previous projects to abdullah@3zm.org\n🤠", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cs-swe-mkt/143741/1", "user": "user2528", "ts": 1366979052000, "tid": 143741, "pn": 1}}', 1366979052000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1155527-mkt398', 'stk-user6966', 'MKT 398', 'info', '{"desc": "مو شرط اخوي أنهم مقدمين .\n\nانا لاحظت شخصياً ان طلاب كلية الادارة الصناعة (محاسبة, تسويق, …الخ) من أقل الطلاب دخولاً إلى أقسام كلياتهم في المنتدى (والله أعلم , ربما الأقل دخولاً للمنتدى بين طلاب الجامعة).\n\nلذلك, أنا متأكد بأنك بتلاقيهم “مسنترين” في التيس بوك . لكن للأسف ماعندي رابط صفحة كلية الادارة على التيس بوك (فيس بوك). لأني شخصياً لا استعمل مواقع التواصل الاجتماعي\n\nوموفق ان شاء الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/136734/3", "user": "user6966", "ts": 1357390020000, "tid": 136734, "pn": 3}}', 1357390020000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p83737-mkt398', 'stk-high_voltage', 'MKT 398', 'info', '{"desc": "We’re looking\nfor The\nTop Coop’s\n\nWe have the following vacancies for students who will be coop’s today and business leaders of tomorrow\n\nMarketing\nSystems Engineering\nAccounting/ MIS / Management\n\nPlease e-mail your application to arabia.kfupmcoordinator@unilever.com by November 21st.\n\nApplication forms are availlable at the PR Club (registrar’s building – room 301) or at the CIM Club in building 24.\n\nTests and interviews will be during the period 3rd – 7th December.\n\nFor more information on Coop Recruitment, please contact our campus coordinator in KFUPM, Osama Andijani at 055 4333 288 from 3 – 11 pm, or at the e-mail address above.\n\nFor any other issues you may contact us at\nArnold.Espanar@Unilever.com - Recruitment Coordinator\nTariq.Alkahily@Unilever.com - Recruitment Manager", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop-at-unilever/48968/1", "user": "High_Voltage", "ts": 1131805942000, "tid": 48968, "pn": 1}}', 1131805942000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p615998-mkt398', 'stk-user2316', 'MKT 398', 'info', '{"desc": "السلام عليكم\nصباحكم/مساؤكم ورد 🌹\n\nتعلن شركة جينيرال اليكتريك(GE) عن توفر فرصة لتطبيق البرنامج التعاوني(الكوأب) في دولة الامارات لطلاب الإدارة (MGT,Marketing,). التطبيق سوف يكون في مجال الموارد البشرية(HR)…\n\nفمن لديه رغبة التطبيق في هذا المجال.أرجو منه مراسلتي عن طريق الخاص…🙂\n\nقصي الضراب\nمنسق شركة جينيرال اليكتريك في الجامعة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/88882/1", "user": "user2316", "ts": 1274936167000, "tid": 88882, "pn": 1}}', 1274936167000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p398426-mkt398', 'stk-lotto', 'MKT 398', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته…\n\nاحبتي الاعزاء…تحية طيبة وبعد…\n\nيعتزم المتجر الوطني -الوكيل الوحيد لماركة لوتو في المملكة العربية السعودية ومملكة البحرين والراعي الرسمي لناديي الاتحاد والنصر -\nالى توظيف نخبة من شباب جامعة الملك فهد للبترول والمعادن بنظام عمل كامل او تدريب تعاوني …واليكم التفاصيل\n\n1- التخصص: التسويق -----------------------------المدينة: الرياض (نادي النصر)\n2- **التخصص:**التسويق-------------------------------المدينة: جدة (نادي الاتحاد)\n3- **التخصص:**التسويق ------------------------------المدينة : الاحساء(نادي فتح)\n4- التخصص: ادارة -موارد بشريه--------------------المدينة: الخبر\n\nفالرجاء ممن يرغب في العمل في هذا المجال ارسال السيرة الذاتية الى الايميل التالي:\nomar@matjaralwatany.com\n\nعلما بان الراتب سيحدد بعد المقابله الشخصية\n\nوتقبلو تحياتي،،،،،،،", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/72928/1", "user": "lotto", "ts": 1241412632000, "tid": 72928, "pn": 1}}', 1241412632000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1463800-mkt398', 'stk-mauud777', 'MKT 398', 'info', '{"desc": "إعلان عن توفر فرص تدريب تعاوني\n\nتعلن شركة ولاء بلس ومقرها الرياض عن توفر فرص تدريبية في برنامج التدريب التعاوني وبالتسيق مع إدارة التدريب في عمادة شؤون الطلاب :\n\n· المالية\n\n· المحاسبة\n\n· الإدارة\n\n· نظم المعلومات الإدارية\n\n· التسويق\n\n· علوم الحاسب الآلي\n\no مميزات التدريب: راتب شهري (1500 ريال) + برنامج مزايا وخصومات للمتدرب وعائلته\n\nعلى الراغبين في التقدم على هذه الفرصة التدريبية، مراجعة مبنى 54( ضمن فعالية اليوم المفتوح للتوظيف) – الاستقبال الرئيسي ( رئيس نادي العلاقات العامة الطلابي ) يومي الاثنين والثلاثاء 6-7 ربيع الاول 1438هـ", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/162-163-171/174980/34", "user": "mauud777", "ts": 1480998877000, "tid": 174980, "pn": 34}}', 1480998877000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1475037-mkt398', 'stk-user10275', 'MKT 398', 'info', '{"desc": "Coop Training Program (Saudi National Only)\nCoop Training Program (Saudi National Only):\n\nRiyadh Airports will start our new Coop Training Program. We are looking for student with major:\n\nAviation Management.\nMarketing.\nManagement.\nAccounting.\nEngineering.\nFinance.\nConditions:\n\nTotal internship period: 28 week.\nGPA must be very good and above.\nEnglish must be Excellent.\nhttps://www.linkedin.com/jobs/view/367195824/?alertAction=markasviewed&savedSearchAuthToken=1&AQHzTa2SvGVuWwAAAVyd4amLNMsnPOP7QtjdqSYcS874zMVdbveUQtPBRk3Fmis5LvnC8wjYsLp8Anc0zCr0DA0G3MrbvGbhyJbQ6GgTI_sq4cxFffbyUV3ncBRS15D92pYNeVmE8kzILP5UvLRHOHB46xoRenUza3IKMpGAhhbjgcZQkylWQZsFDT6fe203jSoJyh_UL7AgDOZMR9y4PtE8EHiLC9hLuF9PPlwrRdv0F0CsnE6XfWIIw3ouCQopV3DSjcyJh5JOxO7vOKA0qoVtBnq6ra3Gbnss-xQRBKlAy9Yi_Wn5y08&AaGGDO3OuywpwTuNCdJAhpTL5kT7&savedSearchId=113365575&trk=eml-job-alert-member-details&midToken=AQFAOX5DtDiegA&trkEmail=eml-email_job_alert_single_02-null-4-null-null-7nym8q~j3uk8brm~fi-null-jobs~view&lipi=urn:li:page:email_email_job_alert_single_02;IOo+xprbRICZmE3Oap+ijA==", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/162-163-171/174980/147", "user": "user10275", "ts": 1497307752000, "tid": 174980, "pn": 147}}', 1497307752000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1471463-mkt398', 'stk-gotham', 'MKT 398', 'info', '{"desc": "فرص تدريب ( 3 - 7 اشهر ) للطلاب في جدة والدمام في P&G لعدة تخصصات هندسية وإدارية\n\nWe have opportunities in:\n\nProduct Supply, Supply Chain, Sales, Marketing, HR, IT, and Finance & Accounting\n\nQualifications\n\nCurrently studying toward Bachelor or Master program in any of the following majors: Engineering, Marketing/Sales, Finance & Accounting, Supply Chain, and Human Resources.\nEnglish fluency.\nFluent in English.\nMust be Saudi national or holds one of the GCC nationality.\nJob ID\nIME00000293\nLocations\nJeddah, Makkah, Saudi Arabia\nDammam, Ash Sharaqiyah, Saudi Arabia\n\nStudent Program - Saudi Arabia Internship Program - Internship http://jobs.pgcareers.com/job/-/-/936/3147135?utm_source=twitter.com&utm_medium=social_post&utm_campaign=Procter_and_Gamble_social&ss=paid", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/162-163-171/174980/127", "user": "Gotham", "ts": 1492429106000, "tid": 174980, "pn": 127}}', 1492429106000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1472068-mkt398', 'stk-hasooona30', 'MKT 398', 'info', '{"desc": "تعلن شركة التنمية غدن للتجارة ومقرها جدة عن توفر فرص تدريبية في برنامج التدريب التعاوني وبالتنسيق مع إدارة التدريب في عمادة شؤون الطلاب :\n\n· الهندسة الصناعية والنظم\n\n· الإدارة\n\n· التسويق\n\no مميزات التدريب: راتب شهري 3500 ريال\n\nعلى الراغبين في التقدم على هذه الفرص التدريبية، إرسال السيرة الذاتية من خلال البريد الالكتروني:\n\narwa@ghadan.com.sa", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/162-163-171/174980/138", "user": "hasooona30", "ts": 1493209119000, "tid": 174980, "pn": 138}}', 1493209119000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1290104-mkt398', 'stk-development_eng', 'MKT 398', 'info', '{"desc": "For All COOP candidates\nWe are looking for COOP candidates in the following majors:\n\nICS\nMarketing\nCompany: Rawabi United Safety Services\nEastern province - Khobar , Dhahran\nSalary: 3000 - 4500\nWorking hours: 8:00 - 4:30 Sunday - Thursday\nInterested candidates are welcome to send their CVs to rawabijobs@yahoo.com", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop-opportunity-for-ics-and-marketing/152624/1", "user": "Development_Eng", "ts": 1384849995000, "tid": 152624, "pn": 1}}', 1384849995000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p604258-mkt398', 'stk-user3238', 'MKT 398', 'info', '{"desc": "- أجدني الآن محتارا بين خيارين فيما يتعلق بخطتي الأكاديمية… بين أن أقوم بتأجيل التخرج وزيادة فصل دراسي وهو الأمر الذي ليس مطلوبا مني خصوصا وأني أتقدم في خطتي الأكاديمية كما هو مفترض أن يحدث دون أي تقصير مني! والخيار الآخر هو أن أقوم بتقديم الكوأب ليكون في الفصل الثاني من الجونيور وبالتالي أعود لأدرس فصلين دراسيين بعد التخرج! بالطبع يوجد خيار ثالث وهو أن أدرس مواد الماركتنغ المستوى الرابع والتي يتفرض منطقيا أن أدرسها بعد العودة من الكوأب وبعد أن آدرس أكبر قدر من كورسات الماركتنغ حتى أستطيع فهمها.\n\nلست الوحيد في هذه الإشكالية التي يستبب فيها نظام عرض المواد في فصل واحد فقط من قبل قسم الإدارة والتسويق!\n\nمبدئيا … الخطة المقترحة من الجامعة هي كالتالي:\nيخصص الفصل الدراسي قبل الأخير والصيف الذي يسبقه لبرنامج الكوأب. والفصل الدراسي الأخير يدرس فيه الطالب المواد التالية\nmkt 450 و ،mkt 420 و mgt 448 و mgt449\n\nهذه المواد مليئة بالتطبيقات المبنية على سوق العمل وعلى فهمك للتخصص بشكل كامل من خلال إنهاء جميع المواد التي تسبقها. ولكن مشكلة قسم التسويق والإدارة أنه يصر على أن مادتي 420 و 450 يتم عرضها في الفصل الدراسي الأول فقط!\nالخطة الطبيعية لأي طالب يود التخرج في الوقت المحدد هو أن يخصص الفصل الدراسي الأول من السنة الأخيرة مع الصيف الذي يسبقه للكوأب. هذا يعني أنه لن يستطيع أن يدرس مادتي 420 و450 إلا بإضافة فصل دراسي هو ليس بحاجة إليه بحيث يكون لديه فصلان دراسيان بعد الكوأب. أو أن يدرسها في بداية الجونيور أي قبل ثلاثة فصول دراسية من التخرج وهو ما يلغي فائدة هذين الكورسين المهمين لفهم تخصص التسويق. وهذه الحالة التي أجدني مضطر إليها الآن!\n\nالخيار الأخير الذي أجده أمامي هو أن أجعل الكوأب في الفصل الثاني من الكوأب ويبقي لي سنة كاملة بعده. وهو الأمر الذي لا أحبذه لأني أود دراسة أكبر قدر ممكن من كورسات الماركتنغ التي يغلب عليها الجانب النظري قبل أن أتجه إلى سوق العمل!\n\nأتفهم تماما مشكلة قسم التسويق والإدارة في عدم القدرة على عرض جميع المواد في فصل دراسي واحد وذلك بسبب قلة الطلاب والمدرسين ولكن في حالة مادتي 420 و450 يجب التفكير جديا في عرضها في الفصلين جميعا أو في الفصل الدراسي الثاني ما دام أن الجامعة تجبر الطالب الآن على أن لا يجعل الكوأب آخر مسيرته الجامعية. ولعل قرار عرض هذه المادتين فقط في الفصل الدراسي الأول كان مرتبطا بأن غالبية الطلاب يجعلونه آخر المطاف. أما الآن وقد اختلف الأمر فلم لا يبادر القسم بتغيير نظام عرض المواد بدلا من الإشكالية التي يضع فيها معظم طلاب التسويق ويجعل التفكير في إطالة سنوات الدراسة أمرا محتما؟\n\nآرائكم\nاقتراحاتكم لخطتي الدراسية\nتعليقاتكم\n\nوشكرا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/87953/1", "user": "user3238", "ts": 1273597007000, "tid": 87953, "pn": 1}}', 1273597007000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p604276-mkt398', 'stk-the_golden', 'MKT 398', 'info', '{"desc": "ما أدري عن قسمكم بس في قسمنا لو أنت مصطر تاخذ المادة أو قدرت تجيب لرئيس القسم 10 طلاب يبون المادة … على طول يضيفها القسم … وأعرف كثير من الشباب في قسمنا تعدلت المواد عشانهم … أخر شيء الترم هذا عشان طالب بس تغير وقت كلاس … و وحدة من المواد إلي أنا فيها السمستر هذا السكشن مجرد 3 طلاب مع أنه في 3 سكاشن معروضه السمستر هذا وفيها أتساع بس عشان وقتنا مايسمح ولازم ناخذها …\n\nفما أدري … أوقع قسمكم لازم يكون متفهم للطلاب وأحتياجاتهم … خصوصاً أنك ذكرت أنه أكثر من طالب يعاني من نفس مشكلتك !!!\n\nالحل إلي أقترحه … كلم رئيس القسم وأذكر له مشكلتك … وإذا رفض تتعدل … أقترح عليه قائمة بأسماء طلاب يريدون المواد هذي !!\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/87953/2", "user": "the_golden", "ts": 1273598895000, "tid": 87953, "pn": 2}}', 1273598895000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p605196-mkt398', 'stk-cartman', 'MKT 398', 'info', '{"desc": "في خطة لإعادة بناء الكركليوم من أول وجديد\nوإضافة مواد جديده زي ( Internet marketing (\n\nطبعا حتى لو تمت تطبيقها بيكون تدريجي ويحتاج سنوات\nهذا الحل طويل الاجل\n\nاللي كان المفروض يصير … ان ال 450 خصوصا تنزل في الترم الثاني\nبخصوص ال420 فهي ماتفرق كثير عن بقية الكورسات … تبقى كمان نظريه\n\nال449 وال448 مافيها مشكلة تنزل ترمين\n\nالمشكله الوحيده متعلقه بال450 … الحل الانسب انك تاخذها قبل تطلع كوآب\nوهذا اللي اغلب الطلاب يسوونه\nالمفترض من القسم … انه يعرض الماده هذي الترم الثاني\n\nبس في النهايه من تجربه … اذا اخذت ال450 بدري … وفهمته صح , راح يسهل عليك بقية مواد الماركتينق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/87953/4", "user": "cartman", "ts": 1273737688000, "tid": 87953, "pn": 4}}', 1273737688000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p607069-mkt398', 'stk-mkt_student', 'MKT 398', 'info', '{"desc": "حياك اخوي هادي …\n\nانا أعاني من نفس مشكلتك بالضبط … حرفياً …\n\nرحت للتشيرمان بخصوص هالسالفة … قال ان كل طلاب الماركتنق يعانون من mkt 450 ويتأخر تخرجهم بسببها … ونسميها في القسم مسمار جحا خخخخخ … قلت له طيب خلوها ترم ثاني بدل ما هي أول … قال بيجون طلاب يقولون خلوها ترم اول ! … قلت من باب أولى انك تعطي الأفضلية للطلاب المنتظمين واللي ماشين على الخطه موب واحد حايق ام الدعوه وحامل ألف ماده يصادف الكووب عنده ترم ثاني يخلص منه ويطق الماده ويتخرج وحنا اللي ماشين على الخطه مادة مادة نتأخر صيف وترم بدون وجه حق !!\n\nالغريب انه حتى المواد اللي محددينها ترم اول وترم ثاني ما تضمن انها تجي على كلامهم … 400 و 410 نزلت ترم اول السنة الجايه وقال التشيرمان لو صار عندنا نقص في المدرسين الترم الثاني بنلغيهم ما راح ننزلهم !! … يعني حتى اللي مبرمج خطته على ترتيب القسم في مواد الترم الاول والترم الثاني ممكن تنحاس اموره !!\n\nالموضوع محيّر جدا ما ألومك … لكن أنا يبدو اني باستسلم للأمر الواقع وازيد ترم … في هالحالة بكون مريّح وبامخمخ على التخصص وعلى النشاطات والدورات وبرضو ما اكون مضغوط وقت كتابة الكواب ريبورت … أما الحالة الثانيه لاحظ انه بيكون عندك ترمين 18 ساعه وبتنزل الكواب بدري واخر ترم 15 ساعه … يعني مستحيل تنجز اي شي في هالفتره وبتصير كنك ملحوق هذا غير ان معدلك ممكن يتأثر …\n\nانا فكرت اني اخلص بسرعه وانزل الكواب بدري وافتك … لكن تخيل معي تنزل السنة الجاية 18 وتروح الكواب بدري ولما ترجع الجامعه يغدرون فيك ويصير فيه لخبطه بالمواد واللي ترم اول راحت ترم ثاني والعكس ويزيد عليك ترم ؟! … متخيل الاحباط اللي بيجيك ؟؟ … يعني لو اضمن ان لستة مواد الاترام ما تتغير وثابته 100% ممكن الواحد يفكر يدعس ويضغط عمره … لكن مثل ما 400 و 410 غيروها في ليلة وضحاها ما تضمن الباقي … لذلك العب على المضمون واهم شي استخر …\n\nتحياتي لك …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/87953/5", "user": "MKT_student", "ts": 1273925954000, "tid": 87953, "pn": 5}}', 1273925954000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1408202-mkt398', 'stk-mustafa3', 'MKT 398', 'info', '{"desc": "منقووووووول\n\nعزيزي الطالب / عزيزتي الطالبة\nالسلام عليكم ورحمة الله وبركاته\n\nتعلن الشركتان الرائدتان في مجال الطاقة النووية إي دي إف (EDF) وأريفا (Areva) عن فتح مجال التدريب المهني للطلبة السعوديين المتخصصين في شتى مجالات الهندسة في فرنسا خاصة وفي أوروبا عامة لفترات تتراوح بين 3 إلى 7 أشهر في منشئاتهما النووية والهندسية في فرنسا وألمانيا.\n\nيأتي هذا التدريب ضمن مضي الشركتين في المشروع النووي السلمي السعودي الذي تقوده مدينة الملك عبدالله للطاقة الذرية والمتجددة (KACARE).\n\nتم استضافة أول دفعة تدريب لعدد يقارب 40 طالب سعودي في يونيو 2014 وتكللت بالنجاح بفضل الله، حيث أن خريجي التدريب لدى إي دي إف وأريفا تم إعطاؤهم الأولوية في التوظيف في شركة الكهرباء السعودية ، بالإضافة إلى إثارة الاهتمام للعديد من الشركات الصناعية فيهم.\n\nيجدر بالذكر أن إي دي إف مملوكة للحكومة الفرنسية بنسبة 85% المشغل الرئيسي للكهرباء في فرنسا، تملك وتشغل 58 مفاعل نووي في فرنسا، عوضاً عن نشاطاتها في مجال الطاقة في أكثر من 20 دولة، وأريفا المملوكة بنسبة مماثلة للدولة تخدم ما يفوق 300 مفاعل نووي في العالم في شتى الطرق كالتزويد بالوقود، والتكنلوجيا النووية، وإعادة تدوير الوقود.\n\nللمزيد من المعلومات:\nwww.edf.com\nwww.areva.com\n\nللتواصل والتقديم على التدريب:\nعبدالله بن إبراهيم الحميد\nمدير التسويق والعلاقات العامة\nإي دي إف ، الرياض\nAbdullah.ALhumaid@edf\\-me.com\n00966599955510\n00966115101109\n\nوالله ولي التوفيق ،،،", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/edf-areva/166685/1", "user": "Mustafa3", "ts": 1414522993000, "tid": 166685, "pn": 1}}', 1414522993000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p177668-mkt398', 'stk-animatedude', 'MKT 398', 'info', '{"desc": "مشكورين اخواني على التوضيح بس ارائكم تتضارب مع بعض…راح اوضح وضعي وانتو قولو راح ينزلي ولا لا…\n\nتخصصي تسويق\nخلصت 4 سنين والكواب الصيف ذا وعندي فصل اخير بعد الكواب,تنزلي مكافأة؟\n\nهل انا وضعي زي الاخ اللي هنا؟\n\nhttp://www.skfupm.com/vb/showthread.php?t=10579", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/52244/16", "user": "animatedude", "ts": 1183122485000, "tid": 52244, "pn": 16}}', 1183122485000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p348439-mkt398', 'stk-user2039', 'MKT 398', 'info', '{"desc": "هذه كتابة وجدتها في اوراقي… كتبتها في اول شهر في الكو أب… الفصل الماضي:\n\nفي هذ الفصل الدراسي… اقوم بما يسمى بالتدريب التعاوني وهو تطبيق لما تعلمناه في الدراسة الجامعية…\nوالحقيقة انني في هذا الشهر المنصرم من اصل سبعة اشهر… بدأت تتضح لي معالم لم تكن واضحة…\nوفي هذه الكتابة البسيطة… احب ان اشارك من يهمه الأمر بعض الفوائد التي استفدتها خلال هذا الشهر…\n\nالفائدة الأول: “البـترول… تعلم”\nخلال فترتنا الدراسية يمر علينا بعض المناهج أوالمدرسين يشعروننا اننا لم نستفد منهم شيئاً ولا من المنهج الذي نتعلمه منهم…\nلكن في الحقيقة… انني تعلمت من افشل مدرس الى انجحهم… فالمدرس الذي يعجز عن ايصال اية معلومة مفيدة طوال فصله الدراسي… يـعلمـك انك قادر على الوصول الى المعلومة وحدك… وانك مؤهل لخوض غمار البحث والتعلم الذاتي… والخروج بالنتيجة التي تريد… بل وحتى يعلمك انك قادرٌ على اختراع طرق جديدة للوصول الى المعلومة… او اختلاق معلومات تبدو وكأنها صحيحة…\nوهذه الاخيرة والتي قد يعترض عليها الكثير… لكن حين “يجبرك” معلمك الى اختلاق معلومة… او يطالبك بعمل تعجيزي… وتنجزه له ولو بانجاز مختلق يعجز هو عن اكتشاف اختلاقاتك فيه… لهو تنمية للجانب الابداعي والتخيلي… اضافة الى قدرة الطالب على اكتشاف الاعمال المماثلة لاختلاقاته…\nوكمراجع قانوني او بمسمى آخر مدقق حسابات… يمكنك اكتشاف الحساب المختلق والعمليات المكذوبة…\n\nهذا بالاضافة الى المناهج التي اثبتت جدارتها في الميدان… فيندر ان اواجه شيئاً لم ادرسه سلفا في البترول… الا ماكان من انظمة داخلية أو اعراف خاصة بالمؤسسات أوالشركات…\nحتى بعض المواد التي ظننت عدم حاجتنا اليها… اتضح لي انني بحاجة ماسة الى معرفة مفاهيم هذه التخصصات كالاحصاء مثلا…\n\nالفائدة الثانية: “أنت تصنع نفسك”\nالواقع يشهد ان سوق العمل ملييييء بالفرص التي تنتظر من يقتنصها… لكنها بحاجة فقط الى ذهن متقد… وقلب عازم…\nفالشركات والمؤسسات تفتقر الى الخبراء والمتعلمين التعليم الجيد القادرين على الابداع والتطوير… فاقسام المحاسبة مثلا في اغلب الشركات… يديرها هياكل يندر وجود المواطن السعودي فيهم… وتجده احيانا… مجرد صورة متواجدة في اسماء موظفي القسم… تجنبا لمشاكل انظمة السعودة…\n\nفالتفكير التقليدي البحت… يجمعنا والعالم في اتجاه واحد وعمل واحد…\nبينما المفكر المبدع يخترع لنفسيه طرقا لا يزدحم عليها الناس…\nوهنا تتضح فكرة الميزة التنافسية… أن تقدم مالا يقدمه غيرك…\nمن خدمة او فكرة او اسلوب…\nوبدأ الذهن يتقد بالكثيير من الافكار التي لم تخطر على البال ايام الدراسة… لكن بالوقوف الميداني على الكثير من البيئات “كمراجع” اظهر لي جليا أن المؤسسات والشركات “السعودية” بحاجة الى الطاقات الشابة… وان عواتقها بدأت تتعب من السير على انظمة وافكار المؤسسين وبحاجة الى افكار فتية ناشئة…\nفمثلاً ماتعلمناه في مادة التسويق… ان التسويق هو عبارة عن تلبية لرغبات السوق…\nبينما نجد ان شركات رابحة ضخمة تدر الملاايين من العوائد لا تزال على النظرية الانتاجية القديمة… وبمجرد تعديلات بسيطة… ستظهر نتائج مذهلة في عوائد تلك الشركات…\n\nالفائدة الثالثة… “أنت تثبت نفسك”\nفي بدايتي كمتدرب… وجدت التقدير واستيعاب قدارتي من زملائي السعوديين… نظراً لخلفيتهم المسبقة عن طلبة البترول وتميزهم… لكن الزملاء من سائر الاقاليم الذين لم تتح لهم الفرصة لمعرفة او حتى السماع عن جامعة الملك فهد للبترول والمعادن… قد لا يعيرك اعتبارً… بادئ الأمر… وينظر لك بنظرة استخفاف… ويطلب منك ابسط الطلبات وهو غير متأكد من قدرتك على انجازها كـ\"هل لديك القدرة على حساب مجاميع هذا الجدول؟\" وهل تلخص لي هذه الورقة…\nثم لا يلبث أن يتغير هذا الأسلوب… وتقفز نظرته لك قفزات بمجرد أن يجد انتاجيتك… وقدرتك على استخدام واستيعاب مايعجز هو عن القيام به…\nوهذه الثلاثة ملاحظات او الفوائد هي ماوجدته في هذه الفترة الوجيزة جداً… قد تفتقر الى الدقة…\nلكن هي مشاركة علها تجد من يستفد منها…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/co-op/69227/1", "user": "user2039", "ts": 1231189091000, "tid": 69227, "pn": 1}}', 1231189091000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p849357-mkt398', 'stk-jare7', 'MKT 398', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nبعد اذن صاحب الموضوع… مااعرف وين المفروض اكتب هالموضوع\nيوجد فرص تدريب (COOP)في شركة السلفونات العربية في جدة .\nموظف الموارد البشرية في الشركة طلب مني اخبر الطلاب عن هذه الفرص\nالفرص المتوفرة حاليا للتدريب التعاوني في الشركة :\nهندسة كيميائية(1)\nهندسة صناعية (1)\nمالية (2)\nنظم (1)\nمحاسبة (2)\nادارة (2)\nتسويق (1)\n\nالي يبغى يتدرب عند الشركة او يعرف احد ما حصل شركة للتدريب التعاوني الى الان\nهالفرص موجودة . وللتواصل مع الموظف في الموارد البشرية (حمزة محمد داوود):\nالجوال : 0500110261\nالمكتب:026082258 تحويلة 231\nالايميل : hamza@mqasons.com\n\nوللاستفسار ارجو التواصل المباشر مع الموظف لاني مشغول مع الاختبارات وماادخل المنتدى .\nواذا كان الموضوع مو في مكانه … ارجو من احدكم ان يتفضل ويكتب موضوع جديد في القسم المخصص .\n\nواكرر اعتذاري من صاحب الموضوع … انا كتبت هنا لان اغلب الي عندهم تدريب يدخلون هالموضوع .\nوبالتوفيق للجميع … واعاننا الله واياكم …\nلا تنسوني من دعآئكم .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/107838/41", "user": "jare7", "ts": 1307643469000, "tid": 107838, "pn": 41}}', 1307643469000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1517931-mkt398', 'stk-user8797', 'MKT 398', 'info', '{"desc": "السلام عليكم و رحمة الله و بركاته\n\nفرصة للعمل في شركة نمذجة للتصنيع بالإضافة، شركة ناشئة متخصصة في مجال الطباعة ثلاثية الأبعاد وتصنيع المنتجات المبتكرة. مجال العمل مرتكز على الإبتكار و سيؤثر بشكل جذري في عالم التصنيع خلال السنوات القادمة.\n\nإذا كنت شخص تحب الابتكار و تجربة الغير المألوف فهذا المجال يناسبك.\n\nالفرص المتوفرة:\n\nهندسة ميكانيكية / تدريب تعاوني\nعمارة / تدريب تعاوني - توظيف\nتسويق-إدارة أعمال / تدريب تعاوني - توظيف\nللتقديم: jobs@namthaja.com", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/182439/1", "user": "user8797", "ts": 1576176487000, "tid": 182439, "pn": 1}}', 1576176487000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1489764-mkt398', 'stk-the_aviator', 'MKT 398', 'info', '{"desc": "Human Resources Internship - P&G Saudi Arabia\nSaudi Arabia, Makkah, Jeddah\nFinance & Accounting Internship - P&G Saudi Arabia\nSaudi Arabia, Makkah, Jeddah\nMarketing Internship - P&G Saudi Arabia\nSaudi Arabia, Makkah, Jeddah\nInformation Technology (IT) Internship - P&G Saudi Arabia\nSaudi Arabia, Makkah, Jeddah\nSupply Chain Internship - P&G Saudi Arabia\nSaudi Arabia, Jeddah\nManufacturing/Engineering Internship - P&G Saudi Arabia\nMultiple Locations\nSales Internship - P&G Saudi Arabia\nSaudi Arabia, Makkah, Jeddah\n\nPlant Technician Internship Program - Product Supply\nSaudi Arabia, Makkah, Jeddah\n\nSearch our Job Opportunities at Procter and Gamble{%22key%22:%22custom_fields.othercountry%22,%22value%22:%22saudi%20arabia%22},{%22key%22:%22custom_fields.language%22,%22value%22:%22english%22}]", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/172-173-181/177905/66", "user": "THE_AVIATOR", "ts": 1522082904000, "tid": 177905, "pn": 66}}', 1522082904000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1500549-mkt398', 'stk-_roro1', 'MKT 398', 'info', '{"desc": "فتح التقديم للتدريب التعاوني بالشركة السعودية للتنمية و الإستثمار التقني (تقنية) :\n\nتعلن الشركة السعودية للتنمية والإستثمار التقني بالرياض (شركة حكومية) عن فتح التقديم في برامج التدريب التعاوني في إدارات وأقسام الشركة لطلاب وطالبات الجامعات المتوقع تخرجهم في التخصصات التالية: - إدارة الأعمال - الموارد البشرية - تقنية المعلومات - نظم المعلومات الإدارية - العلاقات العامة - التسويق الشروط: - أن يكون المتقدم من طلبة البكالوريوس المتوقع تخرجهم خلال العام الميلادي الحالي (2018م) في التخصصات الموضحة أعلاه. - أن لا يقل المعدل التراكمي عن (3 من 4) أو (4 من 5). - يفضل من لديهم مشاركات في العمل التطوعي أو الأنشطة الخارجة عن المناهج الدراسية. - إجادة اللغة الإنجليزية. - مهارات قيادية. نبذة عن الشركة: الشركة السعودية للتنمية والاستثمار التقني (تقنية) شركة سعودية حكومية مملوكة لصندوق الاستثمارات العامة تم تأسيسها بأمر ملكي من مجلس الوزراء في 18 رجب 1432هـ، تهتم الشركة بقيادة التنوع الاقتصادي في السعودية بما يواكب احتياجاتها الاقتصادية من خلال الصناعات القائمة على المعرفة لخلق وظائف ذات قيمة مضافة والمساهمة في تطوير النظام البيئي للابتكار في السعودية، طريقة التقديم: التقديم متاح حالياً من موقع الشركة.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/172-173-181/177905/97", "user": "_Roro1", "ts": 1538950208000, "tid": 177905, "pn": 97}}', 1538950208000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
